import XCTest
@testable import LoopStrapEngine
import Foundation

// MARK: - Welch PSD parity tests (HRV-04)

/// Oracle parity tests for Phase 5 Welch PSD vs scipy.welch ground truth.
///
/// Uses `Resources/fixtures/welch_psd/welch_psd.json` — 5 synthetic-signal cases
/// generated by `export_frequency_fixtures.py`. Each case asserts element-wise
/// absolute tolerance (atol=1e-4) on the normalized post-average power spectrum.
final class WelchPSDParityTests: XCTestCase {

    // MARK: Welch PSD parity

    func testWelchPSDParity() throws {
        let config = try ToleranceConfig.load()
        let url = try resourceURL("welch_psd", "json")
        let fixture = try JSONDecoder().decode(FixtureFile.self, from: Data(contentsOf: url))
        XCTAssertGreaterThan(fixture.cases.count, 0)
        let tolerance = config.spec(for: "welch_psd")

        for testCase in fixture.cases {
            // Extract signal input.
            guard let signalVals = testCase.inputs["signal"]?.arrayOfDoubles else {
                XCTFail("\(testCase.name): missing or malformed signal input"); continue
            }
            // Extract sampling_rate (default 100.0 if missing).
            let samplingRate: Double
            if let srFV = testCase.inputs["sampling_rate"], let sr = srFV.doubleValue {
                samplingRate = sr
            } else {
                samplingRate = 100.0
            }
            // Extract min_frequency — affects nperseg and therefore bin count.
            // Must match what the oracle used; default 0.04 if not specified in fixture.
            let minFrequency: Double
            if let mfFV = testCase.inputs["min_frequency"], let mf = mfFV.doubleValue {
                minFrequency = mf
            } else {
                minFrequency = 0.04
            }

            // Extract expected frequencies and power from the object-shaped output.
            guard case .object(let outputObj) = testCase.output,
                  let freqsFV = outputObj["frequencies"],
                  let expectedFreqs = freqsFV.arrayOfDoubles,
                  let powerFV = outputObj["power"],
                  let expectedPow = powerFV.arrayOfDoubles
            else {
                XCTFail("\(testCase.name): malformed output object — expected {frequencies:[...], power:[...]}"); continue
            }

            // Call the Swift implementation.
            let (actualFreqs, actualPow) = welchPSD(signalVals,
                                                     samplingRate: samplingRate,
                                                     minFrequency: minFrequency)

            // Edge case: all-zero or constant signal — Swift guard fires (maxP == 0) and returns
            // empty arrays. The oracle records zeros as power values. Accept this as guard behaviour.
            if actualFreqs.isEmpty {
                let allExpectedZero = expectedPow.allSatisfy { $0 == 0.0 }
                if allExpectedZero {
                    // Both are effectively "no usable spectrum" — guard case is acceptable.
                    continue
                }
                XCTFail("\(testCase.name): Swift returned empty arrays but oracle has non-zero power bins")
                continue
            }

            // Bin count must match oracle.
            XCTAssertEqual(
                actualFreqs.count, expectedFreqs.count,
                "\(testCase.name): frequency bin count mismatch (actual \(actualFreqs.count) vs expected \(expectedFreqs.count))"
            )
            XCTAssertEqual(
                actualPow.count, expectedPow.count,
                "\(testCase.name): power bin count mismatch (actual \(actualPow.count) vs expected \(expectedPow.count))"
            )

            // Element-wise absolute parity on power bins.
            for (idx, (a, e)) in zip(actualPow, expectedPow).enumerated() {
                if e.isNaN {
                    XCTFail("\(testCase.name): unexpected NaN in oracle power bin \(idx)")
                    continue
                }
                assertParity(actual: a, expected: e, tolerance: tolerance)
            }
        }
    }
}

// MARK: - HRV frequency parity tests (HRV-05)

/// Oracle parity tests for Phase 5 hrv_frequency LF/HF session-level Spearman ρ.
///
/// Uses `Resources/fixtures/hrv_frequency/hrv_frequency_session.json` — 1645 per-epoch
/// cases from a full night of sleep. Tests Spearman ρ ≥ 0.90 on LF and HF arrays across
/// all valid (non-NaN) epochs to verify rank-order concordance with the Python oracle.
final class HRVFrequencyParityTests: XCTestCase {

    // MARK: HRV frequency Spearman ρ session gate

    func testHRVFrequencySpearman() throws {
        let url = try resourceURL("hrv_frequency_session", "json")
        let fixture = try JSONDecoder().decode(FixtureFile.self, from: Data(contentsOf: url))
        XCTAssertGreaterThan(fixture.cases.count, 0)

        var actualLFs:   [Double] = []
        var actualHFs:   [Double] = []
        var expectedLFs: [Double] = []
        var expectedHFs: [Double] = []

        for testCase in fixture.cases {
            // Extract rr_ms input.
            guard let rrMs = testCase.inputs["rr_ms"]?.arrayOfDoubles else {
                XCTFail("\(testCase.name): missing or malformed rr_ms input"); continue
            }

            // Call the Swift implementation.
            let result = hrvFrequency(rrMs)
            actualLFs.append(result.lf)
            actualHFs.append(result.hf)

            // Extract expected lf and hf from the object-shaped output.
            guard case .object(let outputObj) = testCase.output,
                  let lfFV = outputObj["lf"],
                  let hfFV = outputObj["hf"]
            else {
                XCTFail("\(testCase.name): malformed output object — expected {lf:..., hf:..., lfhf:...}"); continue
            }

            // FixtureValue decodes "NaN" sentinels as .double(.nan) via JSONDouble.
            let eLF: Double
            switch lfFV {
            case .double(let d): eLF = d
            default:
                XCTFail("\(testCase.name): unexpected non-double lf in output"); continue
            }
            let eHF: Double
            switch hfFV {
            case .double(let d): eHF = d
            default:
                XCTFail("\(testCase.name): unexpected non-double hf in output"); continue
            }
            expectedLFs.append(eLF)
            expectedHFs.append(eHF)
        }

        // Spearman ρ ≥ 0.90 on LF and HF arrays (NaN-expected pairs filtered internally).
        assertSpearmanParity(actual: actualLFs, expected: expectedLFs, rhoMin: 0.90, message: "LF Spearman ρ")
        assertSpearmanParity(actual: actualHFs, expected: expectedHFs, rhoMin: 0.90, message: "HF Spearman ρ")
    }
}
